def afe_truncation_oversized(q: int, t_max: float, oversize: float = 8.0) -> int:
    """Oversized AFE truncation for accurate L without Riemann-Siegel
    correction terms. The balanced AFE remainder at N = sqrt(qt/2pi) is
    O(1/sqrt(N)) but with constants ~1 in absolute terms; we need
    L-values accurate to ~1e-3 to reliably bracket zeros. Oversizing
    N by ~8x gives error ~ 8^{-1/2} * (1) ~ 0.35 -- still rough. Use 8x
    here as a starting point for slot 3, expecting to refine in
    follow-on slots."""
    return max(int(math.ceil(oversize * math.sqrt(q * t_max / (2.0 * math.pi)))), 30)

